document.addEventListener('DOMContentLoaded',()=>{const host=document.querySelector('.real-map');if(!host)return;const css=document.createElement('link');css.rel='stylesheet';css.href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';document.head.appendChild(css);const js=document.createElement('script');js.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';js.onload=()=>{host.innerHTML='<div id="leaflet-map"></div>';const map=L.map('leaflet-map').setView([-23.006,-44.318],11);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(map);const points=[['Praia do Aventureiro',-23.188,-44.315],['Praia Grande',-23.006,-44.323],['Ilha da Gipóia',-23.047,-44.290],['Ilha Cataguás',-23.018,-44.295],['Vila do Abraão',-23.143,-44.166],['Lagoa Azul',-23.105,-44.255],['Praia de Lopes Mendes',-23.174,-44.143],['Pico do Papagaio',-23.155,-44.185]];const markers={};points.forEach((p,n)=>{markers[p[0]]=L.marker([p[1],p[2]]).addTo(map).bindPopup(`<b>${p[0]}</b><br><button onclick="document.querySelector('#title').textContent='${p[0]}'">Ver no card</button>`)});const title=document.querySelector('#title');new MutationObserver(()=>{const m=markers[title.textContent];if(m){map.setView(m.getLatLng(),13);m.openPopup()}}).observe(title,{childList:true,characterData:true,subtree:true});setTimeout(()=>map.invalidateSize(),300)};document.body.appendChild(js);const s=document.createElement('style');s.textContent='#leaflet-map{height:100%;min-height:235px}.real-map{height:235px}';document.head.appendChild(s)});
